using System;using System.Collections.Generic;using System.Linq;using System.Reflection;
// Offline test facades only. The production MiniShotNative.cs is compiled unchanged.
namespace UnityEngine {
 public class MonoBehaviour {} public sealed class AudioClip {public string Name;public AudioClip(string name){Name=name;}}
 public struct Vector3 {public float x,y,z;public Vector3(float x,float y,float z){this.x=x;this.y=y;this.z=z;}}
 public sealed class GameObject {public readonly string Name;public bool Active=true;public readonly List<bool> Changes=new List<bool>();public GameObject(string name){Name=name;}public void SetActive(bool active){Active=active;Changes.Add(active);}}
}
namespace SpatialWallpaper.Sdk {
 [AttributeUsage(AttributeTargets.Class)]public sealed class WallpaperScriptAttribute:Attribute {}
 public static class Sound {public sealed class Event {public string Kind;public UnityEngine.AudioClip Clip;public float Gain;}public static readonly List<Event> Events=new List<Event>();public static void PlayMusic(UnityEngine.AudioClip clip,float gain){Events.Add(new Event{Kind="music",Clip=clip,Gain=gain});}public static void PlayEffect(UnityEngine.AudioClip clip,float gain){Events.Add(new Event{Kind="effect",Clip=clip,Gain=gain});}}
 public static class Input {public static bool Focused=true;public static string Button;public static float X=.5f,Y=.5f;public static bool IsFocused()=>Focused;public static bool GetButtonDown(string name)=>Button==name;public static float GetPointerX()=>X;public static float GetPointerY()=>Y;}
 public static class View {public static UnityEngine.Vector3 Eye=new UnityEngine.Vector3(0,0,-1),Size=new UnityEngine.Vector3(.53f,.3f,0);public static int EyeReads,SizeReads;public static UnityEngine.Vector3 GetEye(){EyeReads++;return Eye;}public static UnityEngine.Vector3 GetSize(){SizeReads++;return Size;}}
 public static class Storage {
  public sealed class Request {public int Id,Due,State=1,Started;public bool Write;public string Key,Value,Expected,Version,Error;}
  public static readonly Dictionary<string,string> Saved=new Dictionary<string,string>();public static readonly List<Request> History=new List<Request>();static readonly Dictionary<int,Request> requests=new Dictionary<int,Request>();public static int Clock,Delay=1,Next;public static long GlobalVersion;public static string FailNext;public static bool RefuseNext;
  public static void Reset(bool keepSaved=false){if(!keepSaved){Saved.Clear();GlobalVersion=0;}History.Clear();requests.Clear();Clock=0;Delay=1;Next=0;FailNext=null;RefuseNext=false;}
  static int Begin(string key,string value,string version,bool write){if(RefuseNext){RefuseNext=false;return 0;}var r=new Request{Id=++Next,Key=key,Value=value,Expected=version,Write=write,Due=Clock+Delay,Started=Clock,Error=FailNext};FailNext=null;requests.Add(r.Id,r);History.Add(r);return r.Id;}
  public static int BeginRead(string key)=>Begin(key,null,null,false);public static int BeginWriteText(string key,string value,string expected)=>Begin(key,value,expected,true);public static int State(int id)=>requests.TryGetValue(id,out var r)?r.State:0;public static string Error(int id)=>requests[id].Error;public static string Version(int id)=>requests[id].Version;
  public static string TakeText(int id){var r=requests[id];if(r.State!=3)throw new InvalidOperationException("result-not-ready");requests.Remove(id);return r.Value;}public static void Release(int id){requests.Remove(id);}
  public static void Advance(){Clock++;foreach(var r in requests.Values.ToArray()){if(r.State!=1||r.Due>Clock)continue;if(r.Error!=null){r.State=5;continue;}if(r.Write){if(r.Expected!="v"+GlobalVersion){r.State=5;r.Error="storage-version-conflict";continue;}if(r.Value==null)Saved.Remove(r.Key);else Saved[r.Key]=r.Value;GlobalVersion++;}else Saved.TryGetValue(r.Key,out r.Value);r.Version="v"+GlobalVersion;r.State=3;}}
 }
}
static class MiniShotNativeChecks {
 static int count;static void Yes(bool value,string name){if(!value)throw new Exception(name);count++;Console.WriteLine("PASS\t"+name);}
 static void Call(MiniShotNative script,string method){try{typeof(MiniShotNative).GetMethod(method,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(script,null);}catch(TargetInvocationException error){throw error.InnerException;}}
 static MiniShotNative Create(){var s=new MiniShotNative{centers=new UnityEngine.Vector3[10],radii=new float[10],targets=new UnityEngine.GameObject[10],trails=new UnityEngine.GameObject[10],keys=new string[10],hits=new bool[10],dirty=new bool[10],music=new UnityEngine.AudioClip("music"),hitSound=new UnityEngine.AudioClip("hit"),resetSound=new UnityEngine.AudioClip("reset")};for(int i=0;i<10;i++){s.centers[i]=new UnityEngine.Vector3(i*.1f,0,-.5f);s.radii[i]=.02f;s.targets[i]=new UnityEngine.GameObject("target-"+i);s.trails[i]=new UnityEngine.GameObject("trail-"+i);s.keys[i]="minishot.v1.target-"+(i+1).ToString("00");}return s;}
 static void Reset(){SpatialWallpaper.Sdk.Storage.Reset();SpatialWallpaper.Sdk.Sound.Events.Clear();SpatialWallpaper.Sdk.Input.Button=null;SpatialWallpaper.Sdk.Input.Focused=true;SpatialWallpaper.Sdk.Input.X=.5f;SpatialWallpaper.Sdk.Input.Y=.5f;SpatialWallpaper.Sdk.View.Eye=new UnityEngine.Vector3(0,0,-1);SpatialWallpaper.Sdk.View.Size=new UnityEngine.Vector3(.53f,.3f,0);SpatialWallpaper.Sdk.View.EyeReads=SpatialWallpaper.Sdk.View.SizeReads=0;}
 static void Tick(MiniShotNative s,string button=null,bool advance=true){SpatialWallpaper.Sdk.Input.Button=button;if(advance)SpatialWallpaper.Sdk.Storage.Advance();Call(s,"Update");SpatialWallpaper.Sdk.Input.Button=null;}
 static MiniShotNative Loaded(){var s=Create();Call(s,"Start");for(int i=0;i<10;i++)Tick(s);if(s.phase!=2)throw new Exception("fixture-load-failed");return s;}
 static void Drain(MiniShotNative s){for(int i=0;i<40;i++){if(s.phase==2&&!s.dirty.Any(v=>v))return;Tick(s);}throw new Exception("save-drain-timeout");}
 static int Main(){try{
  Reset();var s=Create();Call(s,"Start");Yes(SpatialWallpaper.Sdk.Sound.Events.Count==1&&SpatialWallpaper.Sdk.Sound.Events[0].Kind=="music"&&ReferenceEquals(SpatialWallpaper.Sdk.Sound.Events[0].Clip,s.music)&&SpatialWallpaper.Sdk.Sound.Events[0].Gain==1,"Start plays original music clip once");Tick(s,advance:false);Yes(s.loading==0&&s.phase==1&&SpatialWallpaper.Sdk.Storage.History.Count==1,"pending read never fabricates synchronous completion");for(int i=0;i<10;i++)Tick(s);Yes(s.phase==2&&s.loading==10&&SpatialWallpaper.Sdk.Storage.History.Select(r=>r.Key).SequenceEqual(s.keys),"loads all ten exact persistent target keys in order");Yes(s.targets.All(o=>o.Active)&&s.trails.All(o=>o.Active),"missing saves restore all target and trail visibility");
  s.centers[0]=new UnityEngine.Vector3(0,0,-.5f);s.centers[1]=new UnityEngine.Vector3(.1f,0,-.5f);Yes(s.Pick(.5f,.5f,new UnityEngine.Vector3(0,0,-1),new UnityEngine.Vector3(.53f,.3f,0))==0&&s.Pick(.5f,.5f,new UnityEngine.Vector3(.2f,0,-1),new UnityEngine.Vector3(.53f,.3f,0))==1,"real eye displacement changes selected target");Yes(s.Pick(.75f,.5f,new UnityEngine.Vector3(0,0,-1),new UnityEngine.Vector3(.8f,.3f,0))==1&&s.Pick(.75f,.5f,new UnityEngine.Vector3(0,0,-1),new UnityEngine.Vector3(.4f,.3f,0))==-1,"author display width changes pointer projection");var pick=Create();for(int i=0;i<10;i++)pick.centers[i]=new UnityEngine.Vector3(2+i,0,-.5f);pick.centers[0]=new UnityEngine.Vector3(0,0,-.5f);pick.centers[1]=new UnityEngine.Vector3(0,0,-.8f);Yes(pick.Pick(.5f,.5f,new UnityEngine.Vector3(0,0,-1),new UnityEngine.Vector3(.53f,.3f,0))==1,"nearest intersected target wins independent of index order");
  pick.hits[1]=true;Yes(pick.Pick(.5f,.5f,new UnityEngine.Vector3(0,0,-1),new UnityEngine.Vector3(.53f,.3f,0))==0,"already hit foreground target no longer occludes rear target");
  int reads=SpatialWallpaper.Sdk.Storage.History.Count;Tick(s,"Primary");Yes(s.hits[0]&&!s.targets[0].Active&&!s.trails[0].Active&&SpatialWallpaper.Sdk.View.EyeReads==1&&SpatialWallpaper.Sdk.View.SizeReads==1,"hit uses actual View and hides exact target plus trail");Yes(SpatialWallpaper.Sdk.Sound.Events.Last().Clip==s.hitSound&&SpatialWallpaper.Sdk.Sound.Events.Last().Gain==.7f,"hit plays original effect and gain");Yes(SpatialWallpaper.Sdk.Storage.History.Count==reads&&SpatialWallpaper.Sdk.Storage.Saved.Count==0,"hit does not queue persistence in same scene tick");SpatialWallpaper.Sdk.Storage.Advance();Yes(SpatialWallpaper.Sdk.Storage.Saved.Count==0,"without a subsequent author tick a hit never reaches persistence");Tick(s);Yes(SpatialWallpaper.Sdk.Storage.History.Last().Write&&SpatialWallpaper.Sdk.Storage.History.Last().Expected=="v0"&&SpatialWallpaper.Sdk.Storage.Saved.Count==0,"following author tick starts truly pending compare-and-swap write");
  SpatialWallpaper.Sdk.View.Eye=new UnityEngine.Vector3(.2f,0,-1);Tick(s,"Primary");Yes(s.hits[1]&&!s.targets[1].Active&&s.dirty[1],"second live View hit remains dirty while first save completes");Tick(s);var writes=SpatialWallpaper.Sdk.Storage.History.Where(r=>r.Write).ToArray();Yes(writes.Length==2&&writes[0].Key==s.keys[0]&&writes[1].Key==s.keys[1]&&writes[1].Expected=="v1","two target writes serialize with updated global CAS version");Drain(s);Yes(SpatialWallpaper.Sdk.Storage.Saved.Count==2&&SpatialWallpaper.Sdk.Storage.GlobalVersion==2,"both independent target hits persist after asynchronous completion");int effects=SpatialWallpaper.Sdk.Sound.Events.Count;Tick(s,"Primary");Yes(SpatialWallpaper.Sdk.Sound.Events.Count==effects,"already hit target does not replay hit effect");
  SpatialWallpaper.Sdk.Storage.Reset(true);SpatialWallpaper.Sdk.Input.Button=null;var restarted=Create();Call(restarted,"Start");for(int i=0;i<10;i++)Tick(restarted);Yes(restarted.hits[0]&&restarted.hits[1]&&!restarted.targets[0].Active&&!restarted.trails[1].Active&&restarted.hits.Skip(2).All(v=>!v),"new script instance restores exact two saved hits and visible remainder");Tick(restarted,"Space");Yes(restarted.hits.All(v=>!v)&&restarted.targets.All(v=>v.Active)&&restarted.trails.All(v=>v.Active)&&SpatialWallpaper.Sdk.Sound.Events.Last().Clip==restarted.resetSound&&SpatialWallpaper.Sdk.Sound.Events.Last().Gain==.65f,"reset restores all target/trail feedback and original reset sound");Yes(!SpatialWallpaper.Sdk.Storage.History.Any(r=>r.Write),"reset also defers persistence until next author tick");Drain(restarted);writes=SpatialWallpaper.Sdk.Storage.History.Where(r=>r.Write).ToArray();Yes(writes.Length==10&&writes.Select(r=>r.Key).SequenceEqual(restarted.keys)&&writes.All(r=>r.Value==null)&&writes.Select(r=>r.Expected).SequenceEqual(Enumerable.Range(2,10).Select(i=>"v"+i)),"reset clears ten keys sequentially using every new global version");Yes(SpatialWallpaper.Sdk.Storage.Saved.Count==0,"asynchronously completed reset removes every persisted target");SpatialWallpaper.Sdk.Storage.Reset(true);var resetReload=Create();Call(resetReload,"Start");for(int i=0;i<10;i++)Tick(resetReload);Yes(resetReload.hits.All(v=>!v)&&resetReload.targets.All(v=>v.Active),"fresh instance after completed reset restores all ten targets");
  Reset();s=Loaded();for(int i=0;i<10;i++)s.centers[i]=new UnityEngine.Vector3(2+i,0,-.5f);s.centers[0]=new UnityEngine.Vector3(0,0,-.5f);s.centers[1]=new UnityEngine.Vector3(0,0,-.8f);Tick(s,"Primary");Yes(s.hits[1]&&!s.hits[0]&&!s.targets[1].Active,"live Update first hits foreground overlapping target");Tick(s,"Primary");Yes(s.hits[0]&&s.hits[1]&&!s.targets[0].Active&&SpatialWallpaper.Sdk.Sound.Events.Count(e=>e.Kind=="effect")==2,"live Update then hits revealed rear target with independent feedback");
  Reset();s=Loaded();SpatialWallpaper.Sdk.Input.Focused=false;Tick(s,"Primary");Yes(!s.hits.Any(v=>v)&&SpatialWallpaper.Sdk.Sound.Events.Count==1,"unfocused click has no hit or sound side effect");
  Reset();SpatialWallpaper.Sdk.Storage.FailNext="disk-failed";s=Create();Call(s,"Start");Tick(s,advance:false);Yes(s.error==null&&s.phase==1,"pending failing read is not surfaced early");Tick(s);Yes(s.phase==4&&s.error=="disk-failed"&&s.loading==0,"asynchronous read error is explicit and does not load fake target state");Tick(s,"Space");for(int i=0;i<10;i++)Tick(s);Yes(s.phase==2,"explicit retry after storage error reloads all saved keys");
  Reset();s=Loaded();Tick(s,"Primary");SpatialWallpaper.Sdk.Storage.FailNext="write-failed";Tick(s);Yes(s.phase==3&&s.error==null&&SpatialWallpaper.Sdk.Storage.Saved.Count==0,"failed write begins pending and never reports synchronous success");Tick(s);Yes(s.phase==4&&s.error=="write-failed"&&SpatialWallpaper.Sdk.Storage.Saved.Count==0,"asynchronous write failure remains explicit without persisted false success");
  Reset();s=Loaded();Tick(s,"Primary");Tick(s);SpatialWallpaper.Sdk.Storage.GlobalVersion++;Tick(s);Yes(s.phase==4&&s.error=="storage-version-conflict"&&SpatialWallpaper.Sdk.Storage.Saved.Count==0,"external global version conflict is surfaced without overwriting save");
  Reset();s=Create();SpatialWallpaper.Sdk.Storage.RefuseNext=true;Call(s,"Start");Tick(s,advance:false);Yes(s.phase==4&&s.error=="storage-request-not-started","refused async request is explicit rather than pending forever");
  Reset();SpatialWallpaper.Sdk.Storage.Saved["minishot.v1.target-01"]="corrupt";s=Create();Call(s,"Start");Tick(s);Yes(s.phase==4&&s.error=="unknown-saved-target-state"&&s.loading==0,"unknown persistent value is rejected rather than counted as a hit");
  Console.WriteLine("TOTAL\t"+count);return 0;
 }catch(Exception error){Console.Error.WriteLine(error);return 1;}}
}
